-- Night train EN 471 "Aurora", Kleeberg to Lindholm, the night of 13 to 14 November 2026.
-- Generated by generate_data.py; built fresh for every query.
-- Times are text in the form 'YYYY-MM-DD HH:MM', so they compare and sort correctly.

CREATE TABLE stations (
  seq INTEGER PRIMARY KEY,
  station TEXT NOT NULL,
  km REAL NOT NULL,
  arrival TEXT,   -- actual so far, planned after that; at Kleeberg: doors open for boarding
  departure TEXT
);


CREATE TABLE passengers (
  ticket_id TEXT PRIMARY KEY,
  name TEXT NOT NULL,
  car INTEGER NOT NULL,
  compartment INTEGER NOT NULL,
  card TEXT NOT NULL,  -- the card that opens the compartment
  board TEXT NOT NULL,
  alight TEXT NOT NULL
);


CREATE TABLE scans (
  scan_id INTEGER PRIMARY KEY,
  time TEXT NOT NULL,
  ticket_id TEXT NOT NULL
);


CREATE TABLE speed (
  time TEXT PRIMARY KEY,
  km REAL NOT NULL,
  kmh INTEGER NOT NULL
);


CREATE TABLE doors (
  event_id INTEGER PRIMARY KEY,
  time TEXT NOT NULL,
  car INTEGER NOT NULL,
  door TEXT NOT NULL,  -- 'A' left, 'B' right
  event TEXT NOT NULL  -- 'open' or 'close'
);


CREATE TABLE taps (
  tap_id INTEGER PRIMARY KEY,
  time TEXT NOT NULL,
  card TEXT NOT NULL,  -- compartment card, or S-.. for staff
  car INTEGER NOT NULL,
  reader TEXT NOT NULL
);


CREATE TABLE orders (
  order_id INTEGER PRIMARY KEY,
  time TEXT NOT NULL,
  card TEXT NOT NULL,  -- the tab it went on
  item TEXT NOT NULL,
  price REAL NOT NULL,
  payer TEXT NOT NULL  -- name on the bank card that paid
);

